patterns-tabs--default.snippet:
import { Component } from '@angular/core';
import { TabListComponent } from './tab-list.component';

@Component({
  selector: 'app-demo',
  imports: [TabListComponent],
  template: `
    <dma-tab-list aria-label="Character sheet" [(selected)]="selected">
        <button dma-tab [panel]="overview">Overview</button>
        <button dma-tab [panel]="stats">Stats</button>
        <button dma-tab [panel]="spells">Spells</button>
        <button dma-tab [panel]="notes">Notes</button>
    </dma-tab-list>
    <dma-tab-panel #overview>
        <p>The class, level, and background of the character.</p>
    </dma-tab-panel>
    <dma-tab-panel #stats>
        <p>The six ability scores and their modifiers.</p>
    </dma-tab-panel>
    <dma-tab-panel #spells>
        <p>The spells the character knows, by level.</p>
    </dma-tab-panel>
    <dma-tab-panel #notes>
        <p>Whatever the player wants to remember.</p>
    </dma-tab-panel>`,
})
export class DemoComponent {
  selected = 0;
  selectedChange(event: unknown) {}
}

patterns-tabs--overflow.snippet:
import { Component } from '@angular/core';
import { TabListComponent } from './tab-list.component';

@Component({
  selector: 'app-demo',
  imports: [TabListComponent],
  template: `
    <dma-tab-list aria-label="Character sheet" [(selected)]="selected">
        <button dma-tab [panel]="overview">Overview</button>
        <button dma-tab [panel]="stats">Stats</button>
        <button dma-tab [panel]="spells">Spells</button>
        @if (moreTabs) {
        <button dma-tab [panel]="inventory">Inventory</button>
        <button dma-tab [panel]="features">Features</button>
        }
        <button dma-tab [panel]="notes">Notes</button>
    </dma-tab-list>
    <dma-tab-panel #overview>
        <p>The class, level, and background of the character.</p>
    </dma-tab-panel>
    <dma-tab-panel #stats>
        <p>The six ability scores and their modifiers.</p>
    </dma-tab-panel>
    <dma-tab-panel #spells>
        <p>The spells the character knows, by level.</p>
    </dma-tab-panel>
    <dma-tab-panel #inventory>
        <p>What the character carries.</p>
    </dma-tab-panel>
    <dma-tab-panel #features>
        <p>The class features of the character.</p>
    </dma-tab-panel>
    <dma-tab-panel #notes>
        <p>Whatever the player wants to remember.</p>
    </dma-tab-panel>`,
})
export class DemoComponent {
  selected = 0;
  moreTabs = true;
  selectedChange(event: unknown) {}
}

